#!/usr/bin/env node
/**
 * 플러그인 버전 올리기 — 버전이 적힌 4곳을 한 번에 맞추고 CHANGELOG 의 "미출시" 절을 그 버전 절로 바꾼다.
 * 커밋·태그·푸시는 하지 않는다(사람이 확인한 뒤 한다). 버전의 뜻은 `docs/refs/compat-policy.md`.
 *
 * 버전이 적힌 곳: package.json · .claude-plugin/plugin.json · .claude-plugin/marketplace.json(metadata · plugins[0])
 * 생성 산출물 머리(`Generated by dt-spec@<버전>`)는 plugin.json 을 읽으므로 따로 맞출 필요가 없다.
 *
 * CLI: node scripts/release.mjs <patch|minor|major|x.y.z> [--date YYYY-MM-DD] [--write]
 *   기본은 미리보기(바뀔 곳만 보인다). --write 로 쓴다.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const PLUGIN_ROOT = fileURLToPath(new URL('..', import.meta.url));
/** 파일 → 그 파일에 `"version": "<x>"` 가 몇 번 있어야 하나 */
export const VERSION_FILES = { 'package.json': 1, '.claude-plugin/plugin.json': 1, '.claude-plugin/marketplace.json': 2 };
export const CHANGELOG = 'CHANGELOG.md';
export const UNRELEASED = '## [미출시]';
const VERSION_RE = /"version":\s*"(\d+\.\d+\.\d+)"/g;
const SEMVER_RE = /^\d+\.\d+\.\d+$/;

/** 파일마다 적힌 버전들. */
export function readVersions(root = PLUGIN_ROOT) {
  return Object.fromEntries(Object.keys(VERSION_FILES).map((f) => [f, [...readFileSync(join(root, f), 'utf8').matchAll(VERSION_RE)].map((m) => m[1])]));
}

/** 4곳이 모두 같은 하나의 버전이면 그 버전, 아니면 문제 목록. */
export function checkVersions(root = PLUGIN_ROOT) {
  const found = readVersions(root);
  const problems = [];
  for (const [f, n] of Object.entries(VERSION_FILES)) if (found[f].length !== n) problems.push(`${f}: "version" 이 ${n}번 있어야 하는데 ${found[f].length}번`);
  const all = new Set(Object.values(found).flat());
  if (all.size > 1) problems.push(`버전이 서로 다르다: ${[...all].join(', ')}`);
  return { version: all.size === 1 ? [...all][0] : null, problems };
}

export function nextVersion(current, kind) {
  if (SEMVER_RE.test(kind)) return kind;
  const [ma, mi, pa] = current.split('.').map(Number);
  if (kind === 'major') return `${ma + 1}.0.0`;
  if (kind === 'minor') return `${ma}.${mi + 1}.0`;
  if (kind === 'patch') return `${ma}.${mi}.${pa + 1}`;
  throw new Error(`patch|minor|major|x.y.z 중 하나: ${kind}`);
}

const cmp = (a, b) => { const x = a.split('.').map(Number); const y = b.split('.').map(Number); for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i]; return 0; };

/** CHANGELOG 맨 위 버전 절의 버전(미출시 절은 건너뛴다). */
export function latestChangelogVersion(text) {
  return text.match(/^## \[(\d+\.\d+\.\d+)\]/m)?.[1] ?? null;
}

/** "미출시" 절 본문(다음 `## [` 직전까지). 비었으면 ''. */
export function unreleasedBody(text) {
  const i = text.indexOf(UNRELEASED);
  if (i < 0) return null;
  const rest = text.slice(i + UNRELEASED.length);
  const end = rest.search(/^## \[/m);
  return (end < 0 ? rest : rest.slice(0, end)).trim();
}

/** 미출시 절을 `## [x.y.z] - 날짜` 로 바꾸고 그 위에 빈 미출시 절을 새로 둔다. */
export function releaseChangelog(text, version, date) {
  const body = unreleasedBody(text);
  if (body == null) throw new Error(`${CHANGELOG} 에 "${UNRELEASED}" 절이 없다`);
  if (!body.replace(/^###.*$/gm, '').trim()) throw new Error(`"${UNRELEASED}" 절이 비었다 — 무엇이 바뀌었는지 적은 뒤 올린다`);
  return text.replace(UNRELEASED, `${UNRELEASED}\n\n## [${version}] - ${date}`);
}

/**
 * @returns {{ from: string, to: string, files: { file: string, before: string, after: string }[] }}
 */
export function planRelease(root, kind, { date = new Date().toISOString().slice(0, 10) } = {}) {
  const { version, problems } = checkVersions(root);
  if (problems.length) throw new Error(`버전이 어긋나 있다 — 먼저 맞춘다:\n  ${problems.join('\n  ')}`);
  const to = nextVersion(version, kind);
  if (cmp(to, version) <= 0) throw new Error(`새 버전 ${to} 이 지금 버전 ${version} 보다 커야 한다`);
  const files = Object.keys(VERSION_FILES).map((f) => {
    const before = readFileSync(join(root, f), 'utf8');
    return { file: f, before, after: before.replace(VERSION_RE, (m, v) => m.replace(v, to)) };
  });
  const cl = readFileSync(join(root, CHANGELOG), 'utf8');
  files.push({ file: CHANGELOG, before: cl, after: releaseChangelog(cl, to, date) });
  return { from: version, to, files };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const kind = args.find((a) => !a.startsWith('--') && args[args.indexOf(a) - 1] !== '--date');
  const di = args.indexOf('--date');
  const root = PLUGIN_ROOT;
  if (!kind) { process.stderr.write('usage: release.mjs <patch|minor|major|x.y.z> [--date YYYY-MM-DD] [--write]\n'); process.exit(2); }
  try {
    const plan = planRelease(root, kind, di >= 0 ? { date: args[di + 1] } : {});
    process.stdout.write(`버전 ${plan.from} → ${plan.to}\n`);
    for (const f of plan.files) process.stdout.write(`  ${f.before === f.after ? '그대로' : '바꿈  '} ${f.file}\n`);
    if (args.includes('--write')) {
      for (const f of plan.files) if (f.before !== f.after) writeFileSync(join(root, f.file), f.after);
      process.stdout.write(`썼다. 다음: 테스트 → git commit -m "release: ${plan.to}" → git tag v${plan.to} → push(태그 포함)\n`);
    } else process.stdout.write('미리보기다 — --write 로 쓴다\n');
  } catch (e) {
    process.stderr.write(`${e.message}\n`);
    process.exit(1);
  }
}
